package com.finanscore.notification.messaging;import com.fasterxml.jackson.databind.ObjectMapper;import com.finanscore.contracts.*;import com.finanscore.notification.application.*;import com.finanscore.notification.infrastructure.*;import com.finanscore.support.idempotency.*;import com.finanscore.support.observability.ObservabilityContext;import com.finanscore.support.outbox.*;import io.opentelemetry.instrumentation.annotations.WithSpan;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Component public class NotificationConsumer{private static final Logger log=LoggerFactory.getLogger(NotificationConsumer.class);private final ObjectMapper om;private final NotificationRepository repo;private final IamUserDirectoryPort users;private final EmailNotificationSender email;private final MinioAttachmentReader attachments;private final IdempotentEventGuard guard;private final OutboxService outbox;public NotificationConsumer(ObjectMapper o,NotificationRepository r,IamUserDirectoryPort u,EmailNotificationSender m,MinioAttachmentReader attachments,IdempotentEventGuard g,OutboxService b){om=o;repo=r;users=u;email=m;this.attachments=attachments;guard=g;outbox=b;}
 @WithSpan("send-notification") @KafkaListener(topics=EventTopics.REPORT_GENERATED,groupId="notification-email") @Transactional public void on(String raw)throws Exception{var e=om.readValue(raw,EventEnvelope.class);try(var ignored=ObservabilityContext.bind(e)){if(guard.alreadyProcessed(e.eventId(),"notification-email"))return;UUID request=UUID.fromString(String.valueOf(e.payload().get("requestId")));UUID report=UUID.fromString(String.valueOf(e.payload().get("reportId")));Long uid=Long.valueOf(String.valueOf(e.payload().get("userId")));if(!repo.existsByRequestIdAndReportId(request,report)){var u=users.get(uid);String objectKey=String.valueOf(e.payload().get("objectKey"));email.send(u.email(),request.toString(),report.toString(),attachments.read(objectKey));var n=new NotificationEntity();n.id=UUID.randomUUID();n.requestId=request;n.userId=uid;n.reportId=report;n.recipientEmail=u.email();n.status="SENT";n.createdAt=Instant.now();repo.save(n);Map<String,Object> p=Map.of("requestId",request.toString(),"userId",uid,"reportId",report.toString(),"channel","EMAIL");outbox.append("NotificationSent",request.toString(),e.correlationId(),e.eventId(),null,"notification-service",p);log.info("Notification sent channel=EMAIL reportId={} recipient={}",report,u.email());}guard.markProcessed(e.eventId(),"notification-email");}}}
